SELECT
IFNULL(SUM(total_scene_count), 0) AS value,
IFNULL(MAX(stat_time), NOW()) AS updateTime,
0 AS warnStatus,
#{timeCycle} AS timeCycle
FROM stat_app_scene_rpt


        AND stat_time BETWEEN #{startTime} AND #{endTime}


        AND stat_time >= #{startTime}


        AND stat_time <= #{endTime}

